//! The real pasteboard. Ignored because it swaps the user's clipboard for a moment; run with
//! `cargo test -p wf-platform --test system_clipboard -- --ignored --test-threads=1`.
#![cfg(target_os = "macos")]

use wf_platform::insert::{Clipboard, ClipboardItem, ClipboardSnapshot, SystemClipboard};

const MARKERS: [&str; 3] = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
];

fn without_markers(snapshot: &ClipboardSnapshot) -> ClipboardSnapshot {
    let items = snapshot.items.iter().map(|item| ClipboardItem {
        formats: item
            .formats
            .iter()
            .filter(|(ty, _)| !MARKERS.contains(&ty.as_str()))
            .cloned()
            .collect(),
    });
    ClipboardSnapshot {
        items: items.collect(),
    }
}

#[test]
#[ignore = "swaps the real clipboard for a moment"]
fn snapshot_write_restore_round_trip() {
    let mut clipboard = SystemClipboard::new();
    let original = clipboard.snapshot().unwrap();

    // Everything is observed first and asserted last, so a failure can't lose the user's data.
    let mark = clipboard.write_text("wispr-free round trip", true).unwrap();
    let written = clipboard.snapshot().unwrap();
    let unchanged_after_write = !clipboard.changed_since(mark);
    let probe = ClipboardSnapshot {
        items: vec![ClipboardItem {
            formats: vec![
                ("public.utf8-plain-text".into(), b"plain".to_vec()),
                ("public.html".into(), b"<b>rich</b>".to_vec()),
            ],
        }],
    };
    let probe_restored = clipboard.restore(probe.clone());
    let probe_read = clipboard.snapshot().unwrap();
    let changed_after_restore = clipboard.changed_since(mark);
    let original_restored = clipboard.restore(original.clone());
    let final_state = clipboard.snapshot().unwrap();

    original_restored.unwrap();
    probe_restored.unwrap();
    assert!(unchanged_after_write);
    assert!(changed_after_restore);
    let formats = &written.items[0].formats;
    let text = formats
        .iter()
        .find(|(ty, _)| ty == "public.utf8-plain-text")
        .map(|(_, bytes)| bytes.as_slice());
    assert_eq!(text, Some(b"wispr-free round trip".as_slice()));
    for marker in MARKERS {
        assert!(formats.iter().any(|(ty, _)| ty == marker), "{marker}");
    }
    assert_eq!(without_markers(&probe_read), probe);
    assert_eq!(without_markers(&final_state), without_markers(&original));
}
